MOTIF_NAME = 'weak enemy groups and capture differential'
MOTIF_DESCRIPTION = 'Returns True when opponent stones trapped in one or two liberty groups plus net captured stones, estimated from parity-adjusted stone counts, clearly outweigh the evaluated side own weak stones.'

def motif(board_rows: list[str], color: str) -> bool:
    N = 19
    opp = 'W' if color == 'B' else 'B'
    seen = [[False] * N for _ in range(N)]
    weak = {'B': 0, 'W': 0}
    cnt = {'B': 0, 'W': 0}
    for r in range(N):
        row = board_rows[r]
        for c in range(N):
            ch = row[c]
            if ch == '.':
                continue
            cnt[ch] += 1
            if seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            size = 0
            libs = set()
            while stack:
                y, x = stack.pop()
                size += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < N and 0 <= nx < N:
                        v = board_rows[ny][nx]
                        if v == '.':
                            libs.add((ny, nx))
                        elif v == ch and not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
            L = len(libs)
            if L == 1:
                weak[ch] += 2 * size
            elif L == 2:
                weak[ch] += size
    capd = cnt[color] - cnt[opp] + (1 if color == 'W' else 0)
    return 2 * (weak[opp] - weak[color]) + capd >= 3

MOTIF_NAME = 'unlimited-ray unanimous enclosure area margin'
MOTIF_DESCRIPTION = 'Deletes one-liberty groups and two-liberty groups that face an adjacent enemy group with four or more liberties, casts unbounded orthogonal rays from every empty point to the first remaining stone in each direction, awards the point only when at least two rays hit stones and every hit is the same color, adds surviving stones, and returns True when the evaluated side leads this strictly-enclosed area by a komi-aware margin.'

def motif(board_rows: list[str], color: str) -> bool:
    N = 19
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    grid = [list(r) for r in board_rows]
    gid = [[-1] * N for _ in range(N)]
    groups = []
    for r in range(N):
        for c in range(N):
            if grid[r][c] == '.' or gid[r][c] >= 0:
                continue
            ch = grid[r][c]
            idx = len(groups)
            stack = [(r, c)]
            gid[r][c] = idx
            cells = [(r, c)]
            libs = set()
            while stack:
                y, x = stack.pop()
                for dy, dx in dirs:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < N and 0 <= nx < N:
                        v = grid[ny][nx]
                        if v == '.':
                            libs.add((ny, nx))
                        elif v == ch and gid[ny][nx] < 0:
                            gid[ny][nx] = idx
                            stack.append((ny, nx))
                            cells.append((ny, nx))
            groups.append((ch, cells, len(libs)))
    dead = [False] * len(groups)
    for i, (ch, cells, nl) in enumerate(groups):
        if nl <= 1:
            dead[i] = True
            continue
        if nl == 2:
            for y, x in cells:
                if dead[i]:
                    break
                for dy, dx in dirs:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < N and 0 <= nx < N:
                        v = grid[ny][nx]
                        if v != '.' and v != ch and groups[gid[ny][nx]][2] >= 4:
                            dead[i] = True
                            break
    for i, (ch, cells, nl) in enumerate(groups):
        if dead[i]:
            for y, x in cells:
                grid[y][x] = '.'
    lft = [[''] * N for _ in range(N)]
    rgt = [[''] * N for _ in range(N)]
    upc = [[''] * N for _ in range(N)]
    dwn = [[''] * N for _ in range(N)]
    for r in range(N):
        row = grid[r]
        last = ''
        for c in range(N):
            lft[r][c] = last
            if row[c] != '.':
                last = row[c]
        last = ''
        for c in range(N - 1, -1, -1):
            rgt[r][c] = last
            if row[c] != '.':
                last = row[c]
    for c in range(N):
        last = ''
        for r in range(N):
            upc[r][c] = last
            if grid[r][c] != '.':
                last = grid[r][c]
        last = ''
        for r in range(N - 1, -1, -1):
            dwn[r][c] = last
            if grid[r][c] != '.':
                last = grid[r][c]
    stB = stW = terrB = terrW = 0
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v == 'B':
                stB += 1
            elif v == 'W':
                stW += 1
            else:
                hb = 0
                hw = 0
                for h in (lft[r][c], rgt[r][c], upc[r][c], dwn[r][c]):
                    if h == 'B':
                        hb += 1
                    elif h == 'W':
                        hw += 1
                if hb >= 2 and hw == 0:
                    terrB += 1
                elif hw >= 2 and hb == 0:
                    terrW += 1
    diff = (stB + terrB) - (stW + terrW)
    val = diff if color == 'B' else -diff
    thr = 7 if color == 'B' else 0
    return val >= thr

MOTIF_NAME = 'perpendicular ray-pair braced territory margin'
MOTIF_DESCRIPTION = 'Deletes one-liberty chains and small hopeless two-liberty chains whose every liberty touches an enemy stone, finds each empty point nearest stone along the four orthogonal directions, awards the point to a color that holds both rays of some perpendicular pair within four steps while no ray meets that color enemy within three, adds surviving stones plus a capture bonus, and returns True when the evaluated side leads this corner-braced territory by a komi-aware margin.'

def motif(board_rows: list[str], color: str) -> bool:
    N = 19
    g = [list(row) for row in board_rows]
    seen = [[False] * N for _ in range(N)]
    dead = []
    for r in range(N):
        for c in range(N):
            ch = g[r][c]
            if ch == '.' or seen[r][c]:
                continue
            seen[r][c] = True
            st = [(r, c)]
            comp = [(r, c)]
            ls = set()
            while st:
                y, x = st.pop()
                if y > 0:
                    v = g[y - 1][x]
                    if v == '.':
                        ls.add((y - 1, x))
                    elif v == ch and not seen[y - 1][x]:
                        seen[y - 1][x] = True; st.append((y - 1, x)); comp.append((y - 1, x))
                if y < 18:
                    v = g[y + 1][x]
                    if v == '.':
                        ls.add((y + 1, x))
                    elif v == ch and not seen[y + 1][x]:
                        seen[y + 1][x] = True; st.append((y + 1, x)); comp.append((y + 1, x))
                if x > 0:
                    v = g[y][x - 1]
                    if v == '.':
                        ls.add((y, x - 1))
                    elif v == ch and not seen[y][x - 1]:
                        seen[y][x - 1] = True; st.append((y, x - 1)); comp.append((y, x - 1))
                if x < 18:
                    v = g[y][x + 1]
                    if v == '.':
                        ls.add((y, x + 1))
                    elif v == ch and not seen[y][x + 1]:
                        seen[y][x + 1] = True; st.append((y, x + 1)); comp.append((y, x + 1))
            nl = len(ls)
            kill = nl <= 1
            if not kill and nl == 2 and len(comp) <= 4:
                en = 'W' if ch == 'B' else 'B'
                kill = True
                for ly, lx in ls:
                    t = False
                    if ly > 0 and g[ly - 1][lx] == en:
                        t = True
                    elif ly < 18 and g[ly + 1][lx] == en:
                        t = True
                    elif lx > 0 and g[ly][lx - 1] == en:
                        t = True
                    elif lx < 18 and g[ly][lx + 1] == en:
                        t = True
                    if not t:
                        kill = False
                        break
            if kill:
                dead.append((ch, comp))
    remB = 0
    remW = 0
    for ch, comp in dead:
        if ch == 'B':
            remB += len(comp)
        else:
            remW += len(comp)
        for y, x in comp:
            g[y][x] = '.'
    Z = '.'
    cu = [[Z] * N for _ in range(N)]
    du = [[0] * N for _ in range(N)]
    for r in range(1, N):
        gp = g[r - 1]; cup = cu[r - 1]; dup = du[r - 1]; cur = cu[r]; dur = du[r]
        for c in range(N):
            v = gp[c]
            if v != '.':
                cur[c] = v; dur[c] = 1
            else:
                cur[c] = cup[c]; dur[c] = dup[c] + 1
    cd = [[Z] * N for _ in range(N)]
    dd = [[0] * N for _ in range(N)]
    for r in range(N - 2, -1, -1):
        gn = g[r + 1]; cdn = cd[r + 1]; ddn = dd[r + 1]; cdr = cd[r]; ddr = dd[r]
        for c in range(N):
            v = gn[c]
            if v != '.':
                cdr[c] = v; ddr[c] = 1
            else:
                cdr[c] = cdn[c]; ddr[c] = ddn[c] + 1
    cl = [[Z] * N for _ in range(N)]
    dl = [[0] * N for _ in range(N)]
    cr = [[Z] * N for _ in range(N)]
    dr = [[0] * N for _ in range(N)]
    for r in range(N):
        gr = g[r]
        clr = cl[r]; dlr = dl[r]
        pc = Z; pd = 0
        for c in range(N):
            if c:
                v = gr[c - 1]
                if v != '.':
                    pc = v; pd = 1
                else:
                    pd += 1
            clr[c] = pc; dlr[c] = pd
        crr = cr[r]; drr = dr[r]
        pc = Z; pd = 0
        for c in range(N - 1, -1, -1):
            if c < 18:
                v = gr[c + 1]
                if v != '.':
                    pc = v; pd = 1
                else:
                    pd += 1
            crr[c] = pc; drr[c] = pd
    ptsB = 0; ptsW = 0; sB = 0; sW = 0
    for r in range(N):
        gr = g[r]
        cur = cu[r]; dur = du[r]; cdr = cd[r]; ddr = dd[r]
        clr = cl[r]; dlr = dl[r]; crr = cr[r]; drr = dr[r]
        for c in range(N):
            v = gr[c]
            if v == 'B':
                sB += 1
                continue
            if v == 'W':
                sW += 1
                continue
            a = cur[c]; da = dur[c]
            b = cdr[c]; db = ddr[c]
            e = clr[c]; de = dlr[c]
            f = crr[c]; df = drr[c]
            wnear = (a == 'W' and da <= 3) or (b == 'W' and db <= 3) or (e == 'W' and de <= 3) or (f == 'W' and df <= 3)
            if not wnear:
                vb = (a == 'B' and da <= 4) or (b == 'B' and db <= 4)
                hb = (e == 'B' and de <= 4) or (f == 'B' and df <= 4)
                if vb and hb:
                    ptsB += 1
                    continue
            bnear = (a == 'B' and da <= 3) or (b == 'B' and db <= 3) or (e == 'B' and de <= 3) or (f == 'B' and df <= 3)
            if not bnear:
                vw = (a == 'W' and da <= 4) or (b == 'W' and db <= 4)
                hw = (e == 'W' and de <= 4) or (f == 'W' and df <= 4)
                if vw and hw:
                    ptsW += 1
    scB = ptsB + sB + remW
    scW = ptsW + sW + remB
    val = scB - scW if color == 'B' else scW - scB
    thr = 4 if color == 'B' else 1
    return val >= thr

MOTIF_NAME = 'contested-region perimeter-share area margin'
MOTIF_DESCRIPTION = 'Removes one-liberty groups as captured, flood-fills each maximal empty region, splits its points between the colors in proportion to their shares of the region stone perimeter so contested and neutral areas yield partial credit, adds live stones, and returns True when the evaluated side leads this proportional area estimate by a komi-aware margin.'

def motif(board_rows: list[str], color: str) -> bool:
    N = 19
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    grid = [list(r) for r in board_rows]
    seen = [[False] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            ch = board_rows[r][c]
            if ch == '.' or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = [(r, c)]
            libs = set()
            while stack:
                y, x = stack.pop()
                for dy, dx in dirs:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < N and 0 <= nx < N:
                        v = board_rows[ny][nx]
                        if v == '.':
                            libs.add((ny, nx))
                        elif v == ch and not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
                            cells.append((ny, nx))
            if len(libs) <= 1:
                for y, x in cells:
                    grid[y][x] = '.'
    signed = 0.0
    for r in range(N):
        grow = grid[r]
        for c in range(N):
            v = grow[c]
            if v == 'B':
                signed += 1.0
            elif v == 'W':
                signed -= 1.0
    vis = [[False] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if grid[r][c] != '.' or vis[r][c]:
                continue
            stack = [(r, c)]
            vis[r][c] = True
            sz = 0
            b = 0
            w = 0
            while stack:
                y, x = stack.pop()
                sz += 1
                for dy, dx in dirs:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < N and 0 <= nx < N:
                        u = grid[ny][nx]
                        if u == '.':
                            if not vis[ny][nx]:
                                vis[ny][nx] = True
                                stack.append((ny, nx))
                        elif u == 'B':
                            b += 1
                        else:
                            w += 1
            t = b + w
            if t:
                signed += sz * (b - w) / t
    val = signed if color == 'B' else -signed
    thr = 9.0 if color == 'B' else 1.0
    return val >= thr

MOTIF_NAME = 'contact fight liberty superiority'
MOTIF_DESCRIPTION = 'Compares liberty counts for every pair of adjacent opposing groups and returns True when the evaluated side holds the liberty advantage in clearly more contact fights than it concedes.'

def motif(board_rows: list[str], color: str) -> bool:
    N = 19
    opp = 'W' if color == 'B' else 'B'
    gid = [[-1] * N for _ in range(N)]
    libs = []
    cols = []
    g = 0
    for r in range(N):
        for c in range(N):
            ch = board_rows[r][c]
            if ch == '.' or gid[r][c] != -1:
                continue
            stack = [(r, c)]
            gid[r][c] = g
            ls = set()
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < N and 0 <= nx < N:
                        v = board_rows[ny][nx]
                        if v == '.':
                            ls.add((ny, nx))
                        elif v == ch and gid[ny][nx] == -1:
                            gid[ny][nx] = g
                            stack.append((ny, nx))
            libs.append(len(ls))
            cols.append(ch)
            g += 1
    pairs = set()
    for r in range(N):
        for c in range(N):
            a = gid[r][c]
            if a == -1:
                continue
            for dy, dx in ((1, 0), (0, 1)):
                ny, nx = r + dy, c + dx
                if 0 <= ny < N and 0 <= nx < N:
                    b = gid[ny][nx]
                    if b != -1 and b != a and cols[a] != cols[b]:
                        pairs.add((min(a, b), max(a, b)))
    score = 0
    for a, b in pairs:
        la, lb = libs[a], libs[b]
        ca = cols[a]
        if ca != color:
            la, lb = lb, la
        if la > lb:
            score += 1
        elif lb > la:
            score -= 1
    thr = 2 if color == 'B' else 1
    return score >= thr

MOTIF_NAME = 'same-color flanked line-segment territory margin'
MOTIF_DESCRIPTION = 'Removes one-liberty groups as captured, scans every row and column for empty runs bracketed on both ends by stones of one color within eight points or by one stone and the board edge within five, awards each such sandwiched run to that color per axis, counts live stones double, and returns True when the evaluated side leads this sandwich-territory area by a komi-aware margin.'

def motif(board_rows: list[str], color: str) -> bool:
    N = 19
    opp = 'W' if color == 'B' else 'B'
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    grid = [list(r) for r in board_rows]
    seen = [[False] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            ch = board_rows[r][c]
            if ch == '.' or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = [(r, c)]
            libset = set()
            while stack:
                y, x = stack.pop()
                for dy, dx in dirs:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < N and 0 <= nx < N:
                        v = board_rows[ny][nx]
                        if v == '.':
                            libset.add((ny, nx))
                        elif v == ch and not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
                            cells.append((ny, nx))
            if len(libset) <= 1:
                for y, x in cells:
                    grid[y][x] = '.'
    score = {'B': 0, 'W': 0}
    for r in range(N):
        row = grid[r]
        for c in range(N):
            v = row[c]
            if v != '.':
                score[v] += 2
    for r in range(N):
        row = grid[r]
        c = 0
        while c < N:
            if row[c] != '.':
                c += 1
                continue
            c0 = c
            while c < N and row[c] == '.':
                c += 1
            ln = c - c0
            lb = row[c0 - 1] if c0 > 0 else ''
            rb = row[c] if c < N else ''
            if lb and rb:
                if lb == rb and ln <= 8:
                    score[lb] += ln
            elif lb:
                if ln <= 5:
                    score[lb] += ln
            elif rb:
                if ln <= 5:
                    score[rb] += ln
    for c in range(N):
        r = 0
        while r < N:
            if grid[r][c] != '.':
                r += 1
                continue
            r0 = r
            while r < N and grid[r][c] == '.':
                r += 1
            ln = r - r0
            tb = grid[r0 - 1][c] if r0 > 0 else ''
            bb = grid[r][c] if r < N else ''
            if tb and bb:
                if tb == bb and ln <= 8:
                    score[tb] += ln
            elif tb:
                if ln <= 5:
                    score[tb] += ln
            elif bb:
                if ln <= 5:
                    score[bb] += ln
    diff = score[color] - score[opp]
    thr = 16 if color == 'B' else 4
    return diff >= thr

MOTIF_NAME = 'capture-parity and eye-mouth shape blend margin'
MOTIF_DESCRIPTION = 'Estimates net captures from black-minus-white stone-count parity for the evaluated side to move, adds a solid-shape differential that counts fully own-wrapped empty eye points as two and interior three-quarter tiger mouths as one after deleting one-liberty groups, and returns True when twice the capture estimate plus the shape edge clears a komi-aware threshold.'

def motif(board_rows: list[str], color: str) -> bool:
    N = 19
    opp = 'W' if color == 'B' else 'B'
    tb = 0
    tw = 0
    for row in board_rows:
        tb += row.count('B')
        tw += row.count('W')
    t = tb - tw
    cap = t if color == 'B' else 1 - t
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    grid = [list(r) for r in board_rows]
    seen = [[False] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            ch = board_rows[r][c]
            if ch == '.' or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = [(r, c)]
            libs = set()
            while stack:
                y, x = stack.pop()
                for dy, dx in dirs:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < N and 0 <= nx < N:
                        v = board_rows[ny][nx]
                        if v == '.':
                            libs.add((ny, nx))
                        elif v == ch and not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
                            cells.append((ny, nx))
            if len(libs) <= 1:
                for y, x in cells:
                    grid[y][x] = '.'
    sb = 0
    sw = 0
    for r in range(N):
        for c in range(N):
            if grid[r][c] != '.':
                continue
            nb = 0
            nw = 0
            k = 0
            for dy, dx in dirs:
                ny, nx = r + dy, c + dx
                if 0 <= ny < N and 0 <= nx < N:
                    k += 1
                    v = grid[ny][nx]
                    if v == 'B':
                        nb += 1
                    elif v == 'W':
                        nw += 1
            if nb == k and k >= 3:
                sb += 2
            elif nw == k and k >= 3:
                sw += 2
            elif k == 4 and nb == 3 and nw == 0:
                sb += 1
            elif k == 4 and nw == 3 and nb == 0:
                sw += 1
    shape = (sb - sw) if color == 'B' else (sw - sb)
    score = 2 * cap + shape
    thr = 5 if color == 'B' else 2
    return score >= thr

MOTIF_NAME = 'capped dual-axis nearest-stone consensus area margin'
MOTIF_DESCRIPTION = 'Removes chains in atari, awards each empty point using the nearest surviving stone within five steps along its row and its column, claiming it only when both axes agree or exactly one axis sees a stone while per-axis ties and cross-axis conflicts stay neutral, adds surviving stones, and fires when the evaluated side leads this consensus area by a komi-aware coverage-scaled threshold.'

def motif(board_rows: list[str], color: str) -> bool:
    N = 19
    g = [list(r) for r in board_rows]
    seen = [[False] * N for _ in range(N)]
    dead = []
    for r in range(N):
        for c in range(N):
            if g[r][c] != '.' and not seen[r][c]:
                col = g[r][c]
                stack = [(r, c)]
                seen[r][c] = True
                cells = [(r, c)]
                libs = set()
                while stack:
                    y, x = stack.pop()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < N and 0 <= nx < N:
                            v = g[ny][nx]
                            if v == '.':
                                libs.add((ny, nx))
                            elif v == col and not seen[ny][nx]:
                                seen[ny][nx] = True
                                stack.append((ny, nx))
                                cells.append((ny, nx))
                if len(libs) <= 1:
                    dead.extend(cells)
    for (y, x) in dead:
        g[y][x] = '.'
    K = 5
    row_o = [[None] * N for _ in range(N)]
    col_o = [[None] * N for _ in range(N)]
    for r in range(N):
        grow = g[r]
        ro = row_o[r]
        lc = [None] * N
        ld = [0] * N
        lastc = None
        lastp = -9
        for c in range(N):
            v = grow[c]
            if v != '.':
                lastc = v
                lastp = c
            elif lastc is not None and c - lastp <= K:
                lc[c] = lastc
                ld[c] = c - lastp
        lastc = None
        lastp = 99
        for c in range(N - 1, -1, -1):
            v = grow[c]
            if v != '.':
                lastc = v
                lastp = c
                continue
            rc = None
            rd = 0
            if lastc is not None and lastp - c <= K:
                rc = lastc
                rd = lastp - c
            a = lc[c]
            if a is None:
                ro[c] = rc
            elif rc is None or a == rc:
