        if savable:
            continue
        best = 0
        for ly, lx in glibs[g]:
            nls = set(glibs[g])
            for dy, dx in dirs:
                ny, nx = ly + dy, lx + dx
                if 0 <= ny < N and 0 <= nx < N:
                    v = board_rows[ny][nx]
                    if v == '.':
                        nls.add((ny, nx))
