                    tgt = cb if v == 'B' else cw
                    for j in range(0, i):
                        py, px = line[j]
                        tgt[py][px] += 1
            last = i
            lastcol = v
        tail = L - last - 1
        if lastcol != '' and 0 < tail <= 2:
            tgt = cb if lastcol == 'B' else cw
            for j in range(last + 1, L):
                py, px = line[j]
                tgt[py][px] += 1
    for c in range(N):
        scan(0, c, 1, 1)
        scan(0, c, 1, -1)
    for r in range(1, N):
        scan(r, 0, 1, 1)
