            libs = set()
            while st:
                y, x = st.pop()
                for dy, dx in D:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < N and 0 <= nx < N:
                        v = board_rows[ny][nx]
                        if v == '.':
                            libs.add((ny, nx))
                        elif v == s and cid[ny][nx] < 0:
                            cid[ny][nx] = k
                            st.append((ny, nx))
                            pts.append((ny, nx))
            chains.append((s, pts, libs))
    nch = len(chains)
    adj = [set() for _ in range(nch)]
    for r in range(N):
        for c in range(N):
            if board_rows[r][c] == '.':
                continue
            i = cid[r][c]
            for dy, dx in ((1, 0), (0, 1)):
                ny, nx = r + dy, c + dx
                if ny < N and nx < N and board_rows[ny][nx] != '.':
                    j = cid[ny][nx]
                    if j != i:
                        adj[i].add(j)
                        adj[j].add(i)
    trapped = {'B': 0, 'W': 0}
    for i in range(nch):
        s, pts, libs = chains[i]
        nl = len(libs)
        if nl == 0 or nl > 3:
            continue
        relief = False
        for j in adj[i]:
            if chains[j][0] != s and len(chains[j][2]) == 1:
                relief = True
                break
        if relief:
            continue
        best = 0
        for L in libs:
            ly, lx = L
            new = set(libs)
            cap = 0
            for dy, dx in D:
                ny, nx = ly + dy, lx + dx
                if 0 <= ny < N and 0 <= nx < N:
                    v = board_rows[ny][nx]
                    if v == '.':
                        new.add((ny, nx))
                    elif v == s:
                        j = cid[ny][nx]
                        if j != i:
                            new |= chains[j][2]
                    else:
                        j = cid[ny][nx]
                        if len(chains[j][2]) == 1:
                            cap += len(chains[j][1])
            new.discard(L)
            t = len(new) + cap
            if t > best:
                best = t
            if best >= 3:
                break
        if best <= 2:
            trapped[s] += min(len(pts), 10) + (2 if nl == 1 else 0)
    val = trapped[opp] - trapped[color]
    thr = 6 if color == 'B' else 3
    return val >= thr

