            kill = len(libs) <= 1
            if not kill and len(libs) == 2:
                en = 'W' if s == 'B' else 'B'
                kill = True
                for ly, lx in libs:
                    t = False
                    for dy, dx in D4:
                        ny, nx = ly + dy, lx + dx
                        if 0 <= ny < N and 0 <= nx < N and board_rows[ny][nx] == en:
                            t = True
                            break
                    if not t:
                        kill = False
                        break
            if kill:
                for y, x in comp:
                    g[y][x] = '.'
    if stones < 24:
        return False
    wfB = wfW = 0
    for r in range(N):
        for c in range(N):
            if g[r][c] != '.':
                continue
            nb = nw = 0
            for dy, dx in D4:
                ny, nx = r + dy, c + dx
                if 0 <= ny < N and 0 <= nx < N:
                    v = g[ny][nx]
                    if v == 'B':
                        nb += 1
                    elif v == 'W':
                        nw += 1
            if nb >= 2 and nw == 0:
                wfB += 1
            elif nw >= 2 and nb == 0:
                wfW += 1
    wfd = (wfB - wfW) if color == 'B' else (wfW - wfB)
    if color == 'B':
        if wfd > 8:
            return False
    else:
        if wfd > 6:
            return False
    def dist(col):
        d = [[9] * N for _ in range(N)]
        q = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == col:
                    d[r][c] = 0
                    q.append((r, c))
        i = 0
        while i < len(q):
            y, x = q[i]
            i += 1
            nd = d[y][x] + 1
            if nd > 6:
                continue
            for dy, dx in D8:
                ny, nx = y + dy, x + dx
                if 0 <= ny < N and 0 <= nx < N and d[ny][nx] > nd:
                    d[ny][nx] = nd
                    q.append((ny, nx))
        return d
    dB = dist('B')
    dW = dist('W')
    pb = pw = 0
    for r in range(N):
        for c in range(N):
            if g[r][c] != '.':
                continue
            touch = False
            for dy, dx in D4:
                ny, nx = r + dy, c + dx
                if 0 <= ny < N and 0 <= nx < N and g[ny][nx] != '.':
                    touch = True
                    break
            if touch:
                continue
            a = dB[r][c]
            b = dW[r][c]
            if a <= 3 and b - a >= 2:
                pb += 1
            elif b <= 3 and a - b >= 2:
                pw += 1
    val = (pb - pw) if color == 'B' else (pw - pb)
    if color == 'B':
        return 5 <= val <= 15
    return 1 <= val <= 10
